   finally{ colourCueGlyph=keepGlyph; CFG.xfPix=keepPix; reloadBarDraw=oRB; try{ if(oF&&!hadF&&Object.prototype.hasOwnProperty.call(ctx,'fillRect')) delete ctx.fillRect; }catch(_f){} ZC=ZC0; ZT=ZT0; try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){} __runPrep(); __topClear(); }
